def minimum_factor_digits(num):
    if num < 10:
        return num
    digits = []
    for digit in range(9, 1, -1):
        while num % digit == 0:
            digits.append(digit)
            num //= digit
    if num != 1:
        return 0
    answer = int(''.join(map(str, reversed(digits))))
    return answer if answer < 2**31 else 0

